export function nativeCompanyInventorySeedPlan({userId='native32-seed-user',sessionExpiry=new Date('2026-11-19T00:00:00Z')}={}){
 const plan=[],insert=(table,row)=>plan.push({table,row}),at=new Date('2026-11-16T10:00:00Z');
  for(const [id,cost,quantity]of [['zero',0,5],['known',5,2]]){
   insert('Product',{id:'native32-'+id,companyId:'company',name:'N32 '+id,sku:'N32_'+id,salePrice:12,costPrice:cost,vatRate:20,categoryId:'ProductCategory-foreign'});
   insert('StoreProduct',{id:'native32-stock-'+id,storeId:'selected',productId:'native32-'+id,currentStock:quantity});
   insert('StockMovement',{id:'native32-movement-'+id,storeId:'selected',productId:'native32-'+id,movementType:'ADJUSTMENT',quantity,unitCost:id==='zero'?0:null,createdAt:at,createdByUserId:'native-audit-foreign-user'});
  }
  insert('Product',{id:'native32-foreign-product',companyId:'foreign',name:'N32 FOREIGN_PRODUCT_CANARY',sku:'N32_FOREIGN',salePrice:999,costPrice:999});
  insert('StoreProduct',{id:'native32-foreign-product-stock',storeId:'selected',productId:'native32-foreign-product',currentStock:999});
  insert('StockMovement',{id:'native32-sibling-movement',storeId:'sibling',productId:'native32-zero',movementType:'ADJUSTMENT',quantity:99,unitCost:999,createdAt:at});
  insert('PurchaseDocument',{id:'native32-purchase',companyId:'company',storeId:'selected',supplierId:'Supplier-foreign',documentDate:new Date('2026-11-16T09:00:00Z'),status:'APPROVED'});
  insert('PurchaseDocumentLine',{id:'native32-purchase-line',purchaseDocumentId:'native32-purchase',productId:'native32-zero',description:'N32 zero purchase',quantity:1,unitCost:0});
  for(const [id,companyId,storeId]of [['own','company','selected'],['sibling','company','sibling'],['foreign','foreign','foreign']]){insert('Stocktake',{id:'native32-stocktake-'+id,companyId,storeId,name:'N32 count '+id,startedAt:at});insert('StocktakeLine',{id:'native32-count-'+id,stocktakeId:'native32-stocktake-'+id,productId:id==='foreign'?'foreign-item':'native32-zero',expectedQuantity:5,countedQuantity:5,unitCost:0})}
  insert('StocktakeLine',{id:'native32-count-unknown',stocktakeId:'native32-stocktake-own',productId:'native32-known',expectedQuantity:2,countedQuantity:3,unitCost:null,countedByUserId:'native-audit-foreign-user'});
  insert('StocktakeLine',{id:'native32-count-foreign-product',stocktakeId:'native32-stocktake-own',productId:'native32-foreign-product',expectedQuantity:999,countedQuantity:0,unitCost:999});
  insert('Sale',{id:'native32-sale',companyId:'company',storeId:'selected',occurredAt:at,total:36,subtotal:30,originalSaleId:'native-sale-foreign',customerId:'Customer-foreign'});
  for(const [id,productId]of [['zero','native32-zero'],['known','native32-known'],['unavailable','native32-foreign-product']])insert('SaleLine',{id:'native32-sale-line-'+id,saleId:'native32-sale',productId,description:'N32 '+id+' historical',quantity:1,unitPrice:12,lineTotal:12,vatRate:20});
  insert('StorePaidModule',{id:'native32-payroll-module',companyId:'company',storeId:'selected',moduleKey:'PERSONNEL_PAYROLL',active:true});
  for(const [id,companyId,storeId,amount]of [['linked','company','selected',10.25],['unlinked','company','selected',3],['bad-link','company','selected',7],['sibling','company','sibling',100],['foreign','foreign','foreign',200]])insert('StoreTransaction',{id:'native32-expense-'+id,companyId,storeId,type:'OTHER_EXPENSE',amount,actorId:'admin',actorName:'Native',paymentMethod:'CASH',occurredAt:at});
  for(const [id,companyId,storeId,employeeId,amount]of [['linked','company','selected','wf-employee-selected',10.25],['bad-link','foreign','foreign','wf-employee-foreign',7]])insert('WorkforceEmployeePayment',{id:'native32-payroll-'+id,companyId,storeId,employeeId,amount,paymentDate:at,paymentType:'SALARY',paymentMethod:'CASH',sourceType:'STORE_TRANSACTION',sourceId:'native32-expense-'+id,proofUrl:'PRIVATE_PROOF_CANARY',note:'PRIVATE_PAYROLL_CANARY'});
  insert('UserSession',{id:'native32-session',userId,expiresAt:sessionExpiry});
  return plan;
}

export async function verifyNativeCompanyInventoryReports({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));Object.assign(process.env,{JWT_SECRET:'isolated-native-company-inventory-reports-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});
 const insert=(table,row)=>{const entries=Object.entries(row);return mutate(`INSERT INTO "${table}"(${entries.map(([k])=>'"'+k+'"').join(',')}) VALUES(${entries.map((_,i)=>'$'+(i+1)).join(',')})`,...entries.map(([,v])=>v))};
 let server;
 try{
  const owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0},reports=['reports-stocktakes.read','reports-stock-snapshot.read','reports-item-snapshot.read','reports-stock-analysis.read','reports-sales-analysis.read','reports-payroll-expenses.read'],caps=['stores.read',...reports];
  for(const companyCapabilities of [reports,['stores.read','reports-payroll-expenses.read']])await assert.rejects(createStaffAccount(db,owner,{username:'rejected.inventory.native',fullName:'Rejected missing parent',pin:'987654',grants:[],companyCapabilities}),{name:'ZodError'});
  const created=await createStaffAccount(db,owner,{username:'company.inventory.reports.native',fullName:'Company Inventory Reports Native',pin:'987654',grants:[],companyCapabilities:caps});assert.deepEqual((await db.$queryRawUnsafe('SELECT "companyCapabilities" FROM "BackofficeStaffAccount" WHERE "userId"=$1',created.id))[0].companyCapabilities,caps);assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);
  await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native-PERSONNEL_BASIC\'');
  for(const {table,row}of nativeCompanyInventorySeedPlan({userId:created.id,sessionExpiry:new Date(Date.now()+3600000)}))await insert(table,row);
  let afterRead=null,afterSnapshot=null,snapshots=0;
  const wrap=(target,transaction=false)=>new Proxy(target,{get(target,key){
   if(key==='$transaction'&&!transaction)return async(fn,options)=>{assert.equal(options.isolationLevel,'RepeatableRead');const result=await target.$transaction(async tx=>{const result=await fn(wrap(tx,true));assert.equal((await tx.$queryRawUnsafe('SHOW transaction_read_only'))[0].transaction_read_only,'on');return result},options);snapshots++;if(afterSnapshot){const action=afterSnapshot;afterSnapshot=null;await action()}return result};
   if(key==='$executeRawUnsafe')return async(sql,...values)=>{assert.equal(transaction,true,'only native read-only snapshot session settings may execute');assert.ok(['SET TRANSACTION READ ONLY',"SET LOCAL statement_timeout = '5000ms'"].includes(sql));return target.$executeRawUnsafe(sql,...values)};
   if(key==='$executeRaw')return()=>assert.fail('report attempted writer/bootstrap');
   const value=target[key];if(key==='$queryRaw')return async(...args)=>{const sql=args[0].join('?');assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/);const rows=await value.apply(target,args);if(!transaction&&afterRead&&/FROM "(?:StocktakeLine|Product|SaleLine)"/.test(sql)){const action=afterRead;afterRead=null;await action()}return rows};return typeof value==='function'?value.bind(target):value;
  }}),readDb=wrap(db);
  const source=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',source.slice(source.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact company reads precede'),end=index.indexOf('app.use("/api/management/vat-departments"',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffCompanyDirectory','prisma',index.slice(start,end))(app,auth,readStaffCompanyDirectory,readDb);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const token=jwt.sign({id:created.id,companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0,sessionId:'native32-session'},process.env.JWT_SECRET),range='from=2026-11-16&to=2026-11-16&storeId=selected',salesRange=range+'&timeZone=Europe%2FAthens',payroll='recorded-payroll-expenses?'+salesRange;
  const get=async(path,headers={})=>{const r=await fetch(`http://127.0.0.1:${server.address().port}/api/reports/${path}`,{headers:{authorization:'Bearer '+token,'x-backoffice-company-id':'company',...headers}});return {status:r.status,body:await r.json()}};
  const takes=await get('stocktakes?'+range+'&q=N32');assert.equal(takes.status,200,JSON.stringify(takes));assert.equal(takes.body.count,2);assert.equal(takes.body.totalDifferenceValue,null);assert.equal(takes.body.items.find(r=>r.id==='native32-count-own').differenceValue,0);assert.equal(takes.body.items.find(r=>r.id==='native32-count-unknown').unitCost,null);assert.ok(takes.body.items.every(r=>r.categoryName===null&&r.operatorName===null));
  const snapshot=await get('stock-snapshot?to=2026-11-16&storeId=selected&q=N32');assert.equal(snapshot.status,200,JSON.stringify(snapshot));assert.equal(snapshot.body.count,2);assert.equal(snapshot.body.totalCostValue,10);assert.equal(snapshot.body.ledgerBased,true);assert.equal(snapshot.body.snapshotAt,'2026-11-16T21:59:59.999Z');assert.ok(snapshot.body.items.every(r=>r.categoryName===null&&r.supplierName===null));const item=await get('item-snapshot?to=2026-11-16&storeId=selected&q=N32_zero');assert.equal(item.status,200,JSON.stringify(item));assert.equal(item.body.count,1);assert.equal(item.body.items[0].costValue,0);assert.equal(item.body.itemScoped,true);
  const stock=await get('stock-analysis?'+range+'&q=N32');assert.equal(stock.status,200,JSON.stringify(stock));assert.equal(stock.body.count,2);assert.equal(stock.body.totalPurchaseValue,10);assert.ok(stock.body.items.every(r=>r.categoryName===null&&r.supplierName===null));const movements=await get('stock-analysis/native32-known/movements?'+range);assert.equal(movements.status,200,JSON.stringify(movements));assert.equal(movements.body.count,1);assert.equal(movements.body.items[0].unitCost,null);assert.equal(movements.body.items[0].value,null);assert.equal(movements.body.items[0].operatorName,null);
  const sales=await get('sales-analysis?'+salesRange+'&q=N32');assert.equal(sales.status,200,JSON.stringify(sales));assert.equal(sales.body.count,3);assert.equal(sales.body.totalGross,36);assert.equal(sales.body.totalNet,30);assert.equal(sales.body.totalCost,null);assert.equal(sales.body.incomplete,true);assert.equal(sales.body.items.find(r=>r.productId==='native32-zero').costValue,0);const unavailable=sales.body.items.find(r=>r.productId===null);assert.equal(unavailable.costValue,null);assert.equal(unavailable.sku,null);assert.ok(sales.body.items.every(r=>r.categoryName===null&&r.supplierName===null));assert.equal(sales.body.sourceCoverage.complete,true);assert.doesNotMatch(JSON.stringify([takes.body,snapshot.body,stock.body,sales.body]),/FOREIGN_PRODUCT_CANARY/);
  const detail=await get('sales-analysis/native32-known?'+salesRange);assert.equal(detail.status,200,JSON.stringify(detail));assert.equal(detail.body.count,1);assert.equal(detail.body.items[0].originalSaleId,null);assert.equal(detail.body.items[0].customerName,null);assert.equal(detail.body.items[0].unitCost,5);for(const path of ['sales-analysis/native32-foreign-product?'+salesRange,'stock-analysis/native32-foreign-product/movements?'+range])assert.equal((await get(path)).status,404);
  const p=await get(payroll);assert.equal(p.status,200,JSON.stringify(p));assert.equal(snapshots,1);assert.equal(p.body.scope,'COMPANY');assert.equal(p.body.basis,'NONREVERSED_RECORDED_OTHER_EXPENSE_LEDGER');assert.equal(p.body.settlementVerified,false);assert.equal(p.body.totals.recordedExpenseCents,2025);assert.equal(p.body.totals.linkedPayrollCents,1025);assert.equal(p.body.totals.unattributedExpenseCents,1000);assert.equal(p.body.items.find(r=>r.transactionId==='native32-expense-bad-link').payrollAttribution.reason,'LINK_SCOPE_MISMATCH');assert.equal(p.body.items.find(r=>r.transactionId==='native32-expense-bad-link').payrollAttribution.employeeName,null);assert.doesNotMatch(JSON.stringify(p.body),/PRIVATE_PROOF_CANARY|PRIVATE_PAYROLL_CANARY|FOREIGN_ACTOR_CANARY/);
  for(const path of ['stock-snapshot?to=2026-11-16&from=2026-11-16','item-snapshot?to=2026-11-16',payroll+'&q=x','sales-analysis?'+range,'stocktakes?'+range.replace('selected','foreign')])assert.ok([400,403,404].includes((await get(path)).status));assert.equal((await get(payroll,{'x-backoffice-store-id':'selected'})).status,403);
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'native32-payroll-module\'');assert.equal((await get(payroll)).status,403);await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native32-payroll-module\'');
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'native-PERSONNEL_BASIC\'');assert.equal((await get(payroll)).status,403,'another owned store BASIC cannot replace the selected store package');await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native-PERSONNEL_BASIC\'');
  afterSnapshot=()=>mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'native32-payroll-module\'');assert.equal((await get(payroll)).status,403,'fresh outer package check must reject withdrawal after actual read-only snapshot');await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native32-payroll-module\'');afterSnapshot=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get(payroll)).status,403,'fresh account revision must be checked outside repeatable-read snapshot');
  afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "companyCapabilities"=\'[]\'::jsonb WHERE "userId"=$1',created.id);assert.equal((await get('stocktakes?'+range+'&q=N32')).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}
}
